query MexFetchGroupInfoJobQuery($id, $include_username, $participants_phash, $query_context) {
  id
  creation_time
  lid
  pn
  username
  username_info {
    creator {
      state
      value
      display_name
      role
      join_time
      group_history_sent
      participants_phash_match
      total_participants_count
      missing_participant_identification
      appeal_status
      appeal_update_time
      limit_sharing {
        limit_sharing_enabled
        lid_migration_state {
          addressing_mode
          properties {
            allow_non_admin_sub_group_creation
            closed_by_membership_approval_mode
            ephemeral {
              expiration_time_in_sec
              locked
              growth_locked2 {
                member_add_mode
                parent_group_jid
                group_safety_check
                properties {
                  allow_admin_reports
                  announcement
                  member_link_mode
                  member_share_group_history_mode
                  membership_approval_mode_enabled
                  membership_approval_request
                  properties {
                    general_chat
                    auto_add_disabled
                    hidden_group
                    properties {
                      capi
                      support
                      __typename
                      username_info {
                        creator {
                          xwa2_group_query_by_id {
                            subject {
                              description {
                                participants {
                                  edges {
                                    node {
                                      xwa2_group_query_by_id {
                                        subject {
                                          description {
                                            participants {
                                              edges {
                                                node {
                                                }
                                              }
                                            }
                                          }
                                        }
                                      }
                                    }
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
